const d = msg.payload;
const f_out = parseFloat(d.f_out ?? d.reg_3000h ?? 0.0);
const f_target = parseFloat(d.f_target ?? d.reg_3001h ?? 0.0);
const current = parseFloat(d.current ?? d.reg_3002h ?? 0.0);
const v_out = parseFloat(d.v_out ?? d.reg_3003h ?? 0.0);
const v_dc = parseFloat(d.v_dc ?? d.reg_3004h ?? 0.0);
const fault_code = parseInt(d.fault_code ?? d.reg_700bh ?? 0, 10);

// InfluxDB 2.0 Line Protocol format:
// measurement,tag_set field_set timestamp
msg.payload = `vfd_telemetry,asset_id=VFD_VM_01 f_out=${f_out},f_target=${f_target},current=${current},v_out=${v_out},v_dc=${v_dc},fault_code=${fault_code}i`;
msg.headers = {
    'Authorization': 'Token rca_super_secret_token_123',
    'Content-Type': 'text/plain; charset=utf-8'
};
return msg;

// Store trip snapshot payload for subsequent assembly
flow.set('latest_trip_data', msg.payload);

// Query preceding 60 seconds of telemetry from InfluxDB
msg.payload = `from(bucket: "telemetry")
  |> range(start: -60s)
  |> filter(fn: (r) => r["_measurement"] == "vfd_telemetry")
  |> pivot(rowKey:["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> sort(columns: ["_time"], desc: false)`;

msg.headers = {
    'Authorization': 'Token rca_super_secret_token_123',
    'Content-Type': 'application/vnd.flux',
    'Accept': 'application/csv'
};
return msg;

const tripData = flow.get('latest_trip_data') || {};
const faultCode = parseInt(tripData.fault_code ?? tripData.reg_700bh ?? 6, 10);

const faultMap = {
    2: "Acceleration Overcurrent (Err02)",
    3: "Deceleration Overcurrent (Err03)",
    6: "Deceleration Overvoltage (Err06) - DC link regeneration surge",
    11: "Motor Thermal Overload (Err11) - parameter F2.03 threshold trip"
};

const faultDescription = faultMap[faultCode] || (`WECON VM VFD Trip Code ${faultCode}`);

// Parse CSV rows returned from InfluxDB Flux query
const csvData = msg.payload || '';
const lines = csvData.trim().split('\n');
const telemetryPoints = [];

let headerIndices = {};
for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line || line.startsWith('#')) continue;
    const cols = line.split(',');
    if (cols.includes('_time')) {
        cols.forEach((col, idx) => { headerIndices[col.trim()] = idx; });
        continue;
    }
    if (headerIndices['_time'] !== undefined) {
        const point = {
            timestamp: cols[headerIndices['_time']] || new Date().toISOString(),
            f_out: parseFloat(cols[headerIndices['f_out']] || 0),
            f_target: parseFloat(cols[headerIndices['f_target']] || 0),
            current: parseFloat(cols[headerIndices['current']] || 0),
            v_out: parseFloat(cols[headerIndices['v_out']] || 0),
            v_dc: parseFloat(cols[headerIndices['v_dc']] || 0),
            fault_code: parseInt(cols[headerIndices['fault_code']] || 0, 10)
        };
        telemetryPoints.push(point);
    }
}

// Fallback if InfluxDB buffer was empty (e.g. immediate trip test)
if (telemetryPoints.length === 0) {
    const nowSec = Math.floor(Date.now() / 1000);
    for (let t = 60; t >= 0; t--) {
        telemetryPoints.push({
            timestamp: nowSec - t,
            f_out: t > 5 ? 45.0 : Math.max(0, 45.0 - (5 - t) * 9),
            f_target: t > 5 ? 45.0 : 0.0,
            current: t > 5 ? 1.4 : (1.4 + (5 - t) * 0.5),
            v_out: t > 5 ? 220 : 180,
            v_dc: t > 5 ? 312.0 : (312.0 + (5 - t) * 85.0),
            fault_code: t === 0 ? faultCode : 0
        });
    }
}

msg.payload = {
    asset_id: "VFD_VM_01",
    fault_code: faultCode,
    fault_description: faultDescription,
    incident_id: "INC-HIL-" + Math.floor(Date.now() / 1000),
    pre_fault_telemetry: telemetryPoints
};

msg.headers = {
    'Content-Type': 'application/json'
};
return msg;
